function createApp(deps) {
  const ctx = makeCtx(deps);
  const app = new Hono3().basePath("/api");
  app.use("*", async (c3, next) => {
    await next();
    c3.header("Cache-Control", "private, no-store");
    c3.header("X-Content-Type-Options", "nosniff");
    c3.header("Referrer-Policy", "no-referrer");
  });
  app.use("*", async (c3, next) => {
    const write = c3.req.method !== "GET" && c3.req.method !== "HEAD";
    if (write) {
      const type = c3.req.header("content-type") ?? "";
      const upload = type.includes("multipart/form-data") && /\/documents$/.test(c3.req.path);
      if (!type.includes("application/json") && !upload) return c3.json({ error: "bad_request" }, 400);
      const origin = c3.req.header("origin");
      if (upload && !origin) return c3.json({ error: "forbidden" }, 403);
      if (origin) {
        let host = "";
        try {
          host = new URL(origin).host;
        } catch {
        }
        if (host !== c3.req.header("host")) return c3.json({ error: "forbidden" }, 403);
      }
    }
    await next();
  });
  app.get("/health", async (c3) => {
    let db = "ready";
    try {
      await deps.db.select({ id: users.id }).from(users).limit(1);
    } catch {
      db = "not set up";
    }
    return c3.json({ ok: db === "ready", auth: deps.auth.name, db }, db === "ready" ? 200 : 503);
  });
  app.route("/", authRoutes(ctx));
  app.route("/", registrationRoutes(ctx));
  app.route("/", patientRoutes(ctx));
  app.route("/", observationRoutes(ctx));
  app.route("/", documentRoutes(ctx));
  app.route("/", exchangeRoutes(ctx));
  app.route("/", languageRoutes(ctx));
  app.route("/", maintenanceRoutes(ctx));
  app.route("/", assistantRoutes(ctx));
  app.route("/", opdRoutes(ctx));
  app.route("/", careRoutes(ctx));
  app.notFound((c3) => c3.json({ error: "not_found", path: c3.req.path }, 404));
  app.onError((err2, c3) => {
    logError(`${c3.req.method} ${c3.req.path}`, err2);
    return c3.json({ error: "server_error" }, 500);
  });
  return app;
}

